/* IMS frontend-stall watchdog: proves the browser -> Grafana -> Postgres
   query pipeline is still alive on every dashboard refresh cycle. If this
   panel goes STALE_MS without being re-invoked, the dashboard's own
   refresh timer has stalled (the "data stops retrieving, requires F5"
   symptom) -- force a full page reload, automating what an operator would
   otherwise do by hand. Safe to prepend to any getOption body: wrapped in
   its own IIFE, touches only window.__imsWatchdog*, never collides with
   panel-local variable names. */
(function (staleMs) {
  if (!window.__imsWatchdog) {
    window.__imsWatchdogTick = Date.now();
    window.__imsWatchdog = setInterval(function () {
      if (Date.now() - window.__imsWatchdogTick > staleMs) {
        window.location.reload();
      }
    }, Math.min(staleMs / 4, 30000));
  }
  window.__imsWatchdogTick = Date.now();
})(240000);

const frame = context.panel.data.series[0];
const fields = {};
frame.fields.forEach((f) => { fields[f.name] = f.values.buffer || f.values; });
const seriesCol = fields['series'];
const machineCol = fields['machine'];
const minCol = fields['min'];
const q1Col = fields['q1'];
const medianCol = fields['median'];
const q3Col = fields['q3'];
const maxCol = fields['max'];

const key = (s, m) => s + '|' + m;
const lookup = {};
for (let i = 0; i < seriesCol.length; i++) {
  lookup[key(seriesCol[i], machineCol[i])] = [minCol[i], q1Col[i], medianCol[i], q3Col[i], maxCol[i]];
}
const machines = Array.from(new Set(Array.from(machineCol))).sort();
const peData = machines.map((m) => lookup[key('PE', m)] || [null, null, null, null, null]);
const jeData = machines.map((m) => lookup[key('JE', m)] || [null, null, null, null, null]);

return {
  backgroundColor: 'transparent',
  tooltip: {
    trigger: 'item',
    backgroundColor: 'rgba(18,22,26,0.95)',
    borderColor: 'rgba(255,255,255,0.12)',
    borderWidth: 1,
    textStyle: { color: '#E8EDF2', fontSize: 12 },
  },
  legend: {
    bottom: 0,
    textStyle: { color: 'rgba(224,224,224,0.85)' },
    data: ['PE', 'JE'],
  },
  grid: { left: 55, right: 20, top: 20, bottom: 50, containLabel: true },
  xAxis: {
    type: 'category',
    data: machines,
    axisLabel: { color: 'rgba(224,224,224,0.85)' },
    axisLine: { lineStyle: { color: 'rgba(255,255,255,0.15)' } },
    splitLine: { show: false },
  },
  yAxis: {
    type: 'value',
    name: 'µm',
    nameTextStyle: { color: 'rgba(224,224,224,0.6)' },
    axisLabel: { color: 'rgba(224,224,224,0.85)' },
    splitLine: { lineStyle: { color: 'rgba(255,255,255,0.06)' } },
  },
  series: [
    { name: 'PE', type: 'boxplot', data: peData, itemStyle: { color: 'rgba(0,242,254,0.16)', borderColor: '#00F2FE', borderWidth: 1.5 } },
    { name: 'JE', type: 'boxplot', data: jeData, itemStyle: { color: 'rgba(59,130,246,0.16)', borderColor: '#3B82F6', borderWidth: 1.5 } },
  ],
};

/* IMS frontend-stall watchdog: proves the browser -> Grafana -> Postgres
   query pipeline is still alive on every dashboard refresh cycle. If this
   panel goes STALE_MS without being re-invoked, the dashboard's own
   refresh timer has stalled (the "data stops retrieving, requires F5"
   symptom) -- force a full page reload, automating what an operator would
   otherwise do by hand. Safe to prepend to any getOption body: wrapped in
   its own IIFE, touches only window.__imsWatchdog*, never collides with
   panel-local variable names. */
(function (staleMs) {
  if (!window.__imsWatchdog) {
    window.__imsWatchdogTick = Date.now();
    window.__imsWatchdog = setInterval(function () {
      if (Date.now() - window.__imsWatchdogTick > staleMs) {
        window.location.reload();
      }
    }, Math.min(staleMs / 4, 30000));
  }
  window.__imsWatchdogTick = Date.now();
})(240000);

const frames = context.panel.data.series;
const frame = frames[0];
const timeField = frame.fields.find((f) => f.type === 'time');
const times = timeField.values.buffer || timeField.values;
const numberFields = frame.fields.filter((f) => f.type === 'number');

function lastNonNull(arr) {
  if (!arr) return null;
  for (let i = arr.length - 1; i >= 0; i--) if (arr[i] != null) return arr[i];
  return null;
}

const uclField = numberFields.find((f) => f.name.indexOf('UCL') !== -1);
const lclField = numberFields.find((f) => f.name.indexOf('LCL') !== -1);
const latestUCL = uclField ? lastNonNull(uclField.values.buffer || uclField.values) : null;
const latestLCL = lclField ? lastNonNull(lclField.values.buffer || lclField.values) : null;

const GRAY = '#8B98A9';
const RED = '#EF4444';

const series = numberFields.map((f) => {
  const values = f.values.buffer || f.values;
  const name = f.name;
  const isLimit = name.indexOf('UCL') !== -1 || name.indexOf('LCL') !== -1;
  const data = [];
  for (let i = 0; i < times.length; i++) data.push([times[i], values[i]]);

  if (isLimit) {
    return {
      name: name,
      type: 'line',
      showSymbol: false,
      connectNulls: true,
      lineStyle: { width: 1.5, type: 'dashed', color: RED },
      itemStyle: { color: RED },
      z: 2,
      data: data,
    };
  }

  const latestVal = lastNonNull(values);
  const outOfControl = latestVal != null && ((latestUCL != null && latestVal > latestUCL) || (latestLCL != null && latestVal < latestLCL));
  return {
    name: name,
    type: 'line',
    showSymbol: false,
    connectNulls: true,
    lineStyle: { width: outOfControl ? 1.5 : 1, color: outOfControl ? RED : GRAY, opacity: outOfControl ? 1 : 0.55 },
    itemStyle: { color: outOfControl ? RED : GRAY },
    z: outOfControl ? 3 : 1,
    data: data,
  };
});

return {
  backgroundColor: 'transparent',
  tooltip: {
    trigger: 'axis',
    backgroundColor: 'rgba(18,22,26,0.95)',
    borderColor: 'rgba(255,255,255,0.12)',
    borderWidth: 1,
    textStyle: { color: '#E8EDF2', fontSize: 12 },
    axisPointer: { lineStyle: { color: 'rgba(255,255,255,0.2)' } },
  },
  legend: {
    type: 'scroll',
    bottom: 0,
    textStyle: { color: 'rgba(224,224,224,0.85)' },
    data: series.map((s) => s.name),
  },
  grid: { left: 55, right: 20, top: 20, bottom: 50, containLabel: true },
  xAxis: {
    type: 'time',
    axisLabel: { color: 'rgba(224,224,224,0.65)' },
    axisLine: { lineStyle: { color: 'rgba(255,255,255,0.15)' } },
    splitLine: { show: false },
  },
  yAxis: {
    type: 'value',
    name: 'mm',
    nameTextStyle: { color: 'rgba(224,224,224,0.6)' },
    axisLabel: { color: 'rgba(224,224,224,0.85)', formatter: (v) => v.toFixed(3) },
    splitLine: { lineStyle: { color: 'rgba(255,255,255,0.06)' } },
  },
  series: series,
};
